const allCandidates = [...paperlordsCandidates, ...pearsonCandidates];
let added = 0, skipped = 0;

for (const p of allCandidates) {
  if (existingCodes.has(p.code)) { skipped++; continue; }
  const entry = {
    code: p.code,
    qualification: p.qualification,
    subject: p.subject,
    unit: p.unit,
    name: p.name,
    session: p.session,
    source: p.source,
  };
  if (p.qp) entry.qp = p.qp;
  if (p.ms) entry.ms = p.ms;
  data.papers.push(entry);
  existingCodes.add(p.code);
  added++;
}

data.updated = new Date().toISOString().slice(0, 10);
writeFileSync(jsonPath, JSON.stringify(data, null, 2) + '\n', 'utf8');
console.log(`Done: added ${added} new papers, skipped ${skipped} duplicates. Total: ${data.papers.length}`);
